/* Contact labels and CRM. */
test("label filter shows only labelled chats",()=>{setView("owner");S.filter="VIP";render();const names=[...document.querySelectorAll(".crow .cn b")].map(b=>b.textContent);eq(names,["Arjun Retail Pvt Ltd"]);S.filter="All";render()});
test("create a label and toggle it on a contact",()=>{S.sheet={type:"clabels",chat:"c9"};render();document.getElementById("newlabel").value="Diwali buyer";act.laddnew();ok(C("c9").labels.includes("Diwali buyer"));ok(S.labels.some(l=>l.name==="Diwali buyer"));act.ltoggle({dataset:{v:"Diwali buyer"}});ok(!C("c9").labels.includes("Diwali buyer"));S.sheet=null});
test("deleting a label removes it from contacts",()=>{C("c9").labels.push("Diwali buyer");act.ldel({dataset:{n:"Diwali buyer"}});ok(!C("c9").labels.includes("Diwali buyer"));ok(!S.labels.some(l=>l.name==="Diwali buyer"))});
test("stage, follow-up and note on a contact",()=>{act.cstage({dataset:{id:"c9",v:"Repeat"}});eq(C("c9").crm.stage,"Repeat");act.cnext({dataset:{id:"c9",d:"0"}});ok(needsYou().some(x=>x.cid==="c9"&&x.t==="Follow up"));act.cnext({dataset:{id:"c9",d:"-1"}});eq(C("c9").crm.next,null);
  go("contact",{id:"c9"});document.getElementById("cnote").value="Likes linen";act.cnote({dataset:{id:"c9"}});eq(C("c9").crm.notes[0].t,"Likes linen");S.stack=[{name:"tab"}]});
test("CRM totals come from the contact's documents",()=>{addDoc({id:"INV-T7",kind:"invoice",chat:"c7",items:[{pid:"p4",qty:10,price:1000}],terms:"Net 15",dueTs:Date.now()-2*864e5,status:"unpaid"});const k=crmOf(C("c7"));eq(k.dues,10500);eq(k.late,1);delete S.docs["INV-T7"]});
test("board filters by stage",()=>{S.crmStage="Repeat";go("customers");const n=document.querySelectorAll(".clist .crow").length;eq(n,S.chats.filter(c=>c.crm&&!c.custOnly&&c.crm.stage==="Repeat").length);S.crmStage="All";S.stack=[{name:"tab"}];render()});
